function build(){ $('#stage').innerHTML=moments.map((m,i)=>`<button class="moment ${i===focused?'current':''}" data-moment="${i}" aria-label="${m.short}: explore moment"><div class="moment-content"><div class="eyebrow"><span class="index">${String(i+1).padStart(2,'0')}</span>${m.type}${i===liveIndex?' · NOW':''}</div><h1>${headlines[i]}</h1><p class="lede">${subtitles[i]}</p><div class="open-hint"><span>↗</span>Step inside this moment</div></div><span class="timestamp">${m.label}</span><div class="art">${art(i)}</div></button>`).join('');$$('[data-moment]').forEach(b=>b.onclick=()=>{if(touchMoved)return;const i=+b.dataset.moment;if(i!==focused){go(i);return}if(!expanded)openDetail(i)});buildAxis();updateUI()}
function buildAxis(){$('#timeAxis').innerHTML=moments.slice(0,liveIndex+1).map((m,i)=>`<button data-axis="${i}" aria-label="Go to ${m.short} at ${m.label}">${m.label}</button>`).join('');$$('[data-axis]').forEach(b=>b.onclick=()=>go(+b.dataset.axis))}
function go(i){target=Math.max(0,Math.min(liveIndex,i));if(reduced)position=target;const index=Math.round(target);if(index!==focused){focused=index;updateUI();if(expanded)fillDetail()} }
function updateUI(){$$('.moment').forEach((b,i)=>{b.classList.toggle('current',i===focused);b.tabIndex=i<=liveIndex&&Math.abs(i-focused)<=1?0:-1;b.setAttribute('aria-hidden',i>liveIndex||Math.abs(i-focused)>1?'true':'false');b.querySelector('.eyebrow').innerHTML=`<span class="index">${String(i+1).padStart(2,'0')}</span>${moments[i].type}${i===liveIndex?' · NOW':''}`});$$('[data-axis]').forEach((b,i)=>{b.classList.toggle('active',i===focused);b.setAttribute('aria-current',i===focused?'step':'false')});$('#chapterCount').textContent=`${String(focused+1).padStart(2,'0')} / ${String(liveIndex+1).padStart(2,'0')}`;$('#positionLabel').textContent=moments[focused].short;document.body.classList.toggle('rewound',focused!==liveIndex);$('#statusText').textContent=focused===liveIndex?'AT THE LIVE EDGE':'REWINDING THE THREAD';$('#earlier').disabled=focused===0;$('#later').disabled=focused===liveIndex}
function animate(now){const dt=Math.min(40,now-lastFrame);lastFrame=now;const rate=1-Math.exp(-dt/100);position+=(target-position)*rate;expansion+=((expanded?1:0)-expansion)*(reduced?1:1-Math.exp(-dt/150));const mobile=innerWidth<=800;const h=$('#experience').clientHeight;const spacing=Math.min(260,h*.42);$$('.moment').forEach((el,i)=>{const d=i-position,a=Math.abs(d);const y=d*spacing;const x=-Math.min(270,d*d*42)*(1-expansion*.7)-expansion*(mobile?0:innerWidth*.17);const scale=(1-Math.min(a*.15,.5))*(1-expansion*.5);const opacity=(i>liveIndex||a>2.3)?0:Math.max(0,1-a*.53)*(1-expansion*.18);el.style.transform=`translate3d(${x}px,calc(-50% + ${y}px),${-a*70}px) scale(${scale}) rotateX(${Math.max(-12,Math.min(12,d*7))}deg)`;el.style.opacity=opacity;el.style.filter=`blur(${Math.max(0,a-.7)*1.3}px)`;el.style.pointerEvents=opacity>.12?'auto':'none';el.style.zIndex=10-Math.round(a*2);});requestAnimationFrame(animate)}
function wheel(e){if($('#modal').open||e.target.closest('.detail'))return;if(e.ctrlKey)return;e.preventDefault();const delta=e.deltaY*(e.deltaMode===1?16:1);go(target+Math.max(-.6,Math.min(.6,delta/420)));clearTimeout(snapTimer);snapTimer=setTimeout(()=>go(Math.round(target)),150)}$('#experience').addEventListener('wheel',wheel,{passive:false});$('#experience').addEventListener('touchstart',e=>{if(e.target.closest('.detail'))return;touchY=e.touches[0].clientY;touchMoved=false},{passive:true});$('#experience').addEventListener('touchmove',e=>{if(touchY===null||e.target.closest('.detail'))return;const y=e.touches[0].clientY;const delta=touchY-y;if(Math.abs(delta)>2)touchMoved=true;go(target+delta/280);touchY=y},{passive:true});$('#experience').addEventListener('touchend',()=>{touchY=null;go(Math.round(target));setTimeout(()=>touchMoved=false,80)});
document.addEventListener('keydown',e=>{if($('#modal').open)return;if(e.key==='Escape'&&expanded){closeDetail();return}if(['ArrowUp','ArrowDown','Home','End'].includes(e.key)&&!e.target.closest('.detail')){e.preventDefault();go(e.key==='Home'?0:e.key==='End'?liveIndex:focused+(e.key==='ArrowUp'?-1:1))}});$('#earlier').onclick=()=>go(focused-1);$('#later').onclick=()=>go(focused+1);$('#returnLive').onclick=()=>{closeDetail();go(liveIndex)};
function openDetail(i){go(i);expanded=true;document.body.classList.add('expanded');$('#detail').hidden=false;fillDetail();$('#closeDetail').focus({preventScroll:true})}function closeDetail(){expanded=false;document.body.classList.remove('expanded');$('#detail').hidden=true;if(focused>=0)$(`[data-moment="${focused}"]`)?.focus({preventScroll:true})}$('#closeDetail').onclick=closeDetail;
function fillDetail(){const m=moments[focused];$('#detail').innerHTML=`<div class="eyebrow">${m.label} &nbsp; / &nbsp; ${m.type}</div><h2>${m.title}</h2><p class="summary">${m.summary}</p><button class="slide-frame" id="slideExpand" aria-label="Expand original slide ${m.slide}"><img src="assets/slide-${String(m.slide).padStart(2,'0')}.png" alt="Original lecture slide ${m.slide}: ${m.short}"><span class="caption"><span>FROM THE LECTURE · SLIDE ${String(m.slide).padStart(2,'0')}</span><span>EXPAND ↗</span></span></button><div class="intuition"><small>THE IDEA TO HOLD ONTO</small><p>${m.intuition}</p></div><div class="detail-actions"><button id="transcript">Read the source ↗</button><button id="save">${saved.includes(focused)?'✓ Moment saved':'+ Save this moment'}</button></div><p class="notes">${m.label.startsWith('≈')?'Estimated timestamp within an untimed transcript passage.':'Timestamp anchored to the lecture transcript.'}</p>`;$('#detail').scrollTop=0;$('#slideExpand').onclick=()=>showModal(`<div class="eyebrow">ORIGINAL MATERIAL · SLIDE ${m.slide} / 13</div><h2>${m.short}</h2><img src="assets/slide-${String(m.slide).padStart(2,'0')}.png" alt="Full original slide ${m.slide}"><p>Limitations of Behavior Cloning · Prof. Scott Niekum</p>`);$('#transcript').onclick=()=>showModal(`<div class="eyebrow">IN THE LECTURE</div><h2>${m.short}</h2><blockquote>“${m.quote}”</blockquote><p>Prof. Scott Niekum · ${m.quoteTime}</p><p class="notes">From the September 15 transcript. Punctuation lightly normalized.</p>`);$('#save').onclick=()=>{saved=saved.includes(focused)?saved.filter(i=>i!==focused):[...saved,focused];try{localStorage.setItem('recall-saved',JSON.stringify(saved))}catch{}$('#save').textContent=saved.includes(focused)?'✓ Moment saved':'+ Save this moment';toast(saved.includes(focused)?'Saved. Find it in the concept map.':'Moment removed from your saved ideas.')}}
