$('#mapButton').onclick=()=>{showModal(`<div class="eyebrow">THE SHAPE OF THIS LECTURE</div><h2>Every thought leads somewhere.</h2><p>From imitation to recovery. Choose a concept to follow its thread.</p><div class="graph">${moments.map((m,i)=>`<button data-node="${i}" class="${i>liveIndex?'future':''}"><span>${m.label} ${saved.includes(i)?' · SAVED':''}${i>liveIndex?' · UPCOMING':''}</span>${m.short}<small>${m.connection}</small></button>`).join('')}</div><p class="notes">Read left to right, then down. Upcoming concepts jump the simulated replay forward. ≈ indicates an estimated timestamp.</p>`);$$('[data-node]').forEach(b=>b.onclick=()=>{const i=+b.dataset.node;if(i>liveIndex){elapsed=moments[i].time;liveIndex=i;buildAxis();$('#clock').textContent=fmt(elapsed)}$('#modal').close();closeDetail();go(i)})};
$('#lectureInfo').onclick=()=>showModal(`<div class="eyebrow">690S · LECTURE 02 · SEPTEMBER 15, 2026</div><h2>When imitation fails.</h2><p>Limitations of Behavior Cloning, taught by Prof. Scott Niekum.</p><p>Scroll up to move into the past, or use the arrow keys. Select the focused thought to open its explanation and slide. Escape returns to the timeline.</p><p class="notes">An interaction prototype using your real lecture slides and transcript. The live session is simulated; no microphone, transcription, or AI service is connected. ≈ marks estimated timestamps. Saved moments stay in this browser.</p>`);
$('#pause').onclick=()=>{playing=!playing;if(elapsed>=3660){elapsed=1990;liveIndex=5;go(5);buildAxis()}document.body.classList.toggle('playing',playing);$('#pause').textContent=playing?'Ⅱ':'▶';$('#pause').setAttribute('aria-label',playing?'Pause simulated lecture':'Play simulated lecture')};setInterval(()=>{if(!playing)return;elapsed=Math.min(3660,elapsed+1);$('#clock').textContent=fmt(elapsed);const next=moments.reduce((v,m,i)=>m.time<=elapsed?i:v,0);if(next>liveIndex){const followed=focused===liveIndex;liveIndex=next;buildAxis();if(followed)go(next);toast('A new thought has joined the thread.')}if(elapsed===3660){playing=false;document.body.classList.remove('playing');$('#pause').textContent='▶';$('#pause').setAttribute('aria-label','Play simulated lecture');toast('Lecture complete. Rewind whenever you need.')}},1000);
